style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com"), domain("create.roblox.com") {
html, body, * {
    background-image: url("data:image/jpeg;base64,") !important;
    background-repeat: repeat !important;
    background-size: 200px auto !important;
    background-attachment: fixed !important;
    background-position: top left !important;
    background-color: #fff9e5 !important;
  }

  /* Make Roblox panels transparent */
  .container-main, .content, .game-card-container, .section, .chat-container, .home-container, .left-col, .right-col, .container-content {
    background-color: transparent !important;
    backdrop-filter: none !important;
  }

  /* Also fix some translucent masks and overlays */
  .overlay, .modal-content, .modal-dialog, .dark-theme {
    background: transparent !important;
  }
}
